/* byte-swap a 128-bit lane of 4 big-endian words */
static inline __m128i bswap32_128(__m128i x){
    const __m128i mask = _mm_setr_epi8(3,2,1,0, 7,6,5,4, 11,10,9,8, 15,14,13,12);
    return _mm_shuffle_epi8(x, mask);
