static inline __m128i s0_128(__m128i x){
    /* s0 = rotr7 ^ rotr18 ^ shr3 */
    __m128i r7  = _mm_or_si128(_mm_srli_epi32(x,7),  _mm_slli_epi32(x,25));
    __m128i r18 = _mm_or_si128(_mm_srli_epi32(x,18), _mm_slli_epi32(x,14));
    __m128i s3  = _mm_srli_epi32(x,3);
    return _mm_xor_si128(_mm_xor_si128(r7, r18), s3);
}
static inline __m128i s1_128(__m128i x){
    __m128i r17 = _mm_or_si128(_mm_srli_epi32(x,17), _mm_slli_epi32(x,15));
    __m128i r19 = _mm_or_si128(_mm_srli_epi32(x,19), _mm_slli_epi32(x,13));
    __m128i s10 = _mm_srli_epi32(x,10);
    return _mm_xor_si128(_mm_xor_si128(r17, r19), s10);
}

#define ROTR(x,n) (((x)>>(n))|((x)<<(32-(n))))

#define ROUND(a,b,c,d,e,f,g,h,kk,ww) do { \
    uint32_t S1 = ROTR(e,6) ^ ROTR(e,11) ^ ROTR(e,25); \
    uint32_t ch = (e & f) ^ ((~e) & g); \
    uint32_t t1 = h + S1 + ch + (kk) + (ww); \
    uint32_t S0 = ROTR(a,2) ^ ROTR(a,13) ^ ROTR(a,22); \
    uint32_t maj = (a & b) ^ (a & c) ^ (b & c); \
    h = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + S0 + maj; \
} while(0)

static void sha256_block(uint32_t state[8], const uint8_t block[64]){
    __m128i w0 = bswap32_128(_mm_loadu_si128((const __m128i*)(block+0)));
    __m128i w1 = bswap32_128(_mm_loadu_si128((const __m128i*)(block+16)));
    __m128i w2 = bswap32_128(_mm_loadu_si128((const __m128i*)(block+32)));
    __m128i w3 = bswap32_128(_mm_loadu_si128((const __m128i*)(block+48)));

    uint32_t a=state[0],b=state[1],c=state[2],d=state[3];
    uint32_t e=state[4],f=state[5],g=state[6],h=state[7];

    uint32_t w[64];
    _mm_storeu_si128((__m128i*)(w+0), w0);
    _mm_storeu_si128((__m128i*)(w+4), w1);
    _mm_storeu_si128((__m128i*)(w+8), w2);
    _mm_storeu_si128((__m128i*)(w+12), w3);

    /* compute message schedule 4 words at a time, interleaved conceptually */
    for(int i=16;i<64;i+=4){
        /* w[i] = w[i-16] + s0(w[i-15]) + w[i-7] + s1(w[i-2])
           vector: for 4 consecutive, the dependencies differ; do scalar-ish via shuffles.
           Use the standard SSE message schedule expansion. */
        /* s0 for w[i-15 .. i-12] */
        __m128i w_im15 = _mm_alignr_epi8(w1, w0, 4); /* w[i-15..i-12] when i=16: w1 starts at w4, alignr gives w1..w4? 
           _mm_alignr_epi8(a,b,n) concatenates a:b and shifts right by n bytes, returns low 16.
           We want words w[i-15],w[i-14],w[i-13],w[i-12] = words index (i-15).
           At start of iteration, w0 holds w[i-16..i-13], w1 holds w[i-12..i-9], w2 w[i-8..i-5], w3 w[i-4..i-1].
           w[i-15..i-12] = last 3 of w0 + first of w1 = alignr(w1, w0, 4)
           w[i-2..i+1] not fully available. Do 4 at a time carefully. */
        __m128i t0 = _mm_alignr_epi8(w1, w0, 4);   /* w[i-15 .. i-12] */
        __m128i s0 = s0_128(t0);
        /* s1 for w[i-2],w[i-1],w[i],w[i+1] — w[i],w[i+1] not yet known. Compute first two scalar-free:
           Standard approach: compute s1 of w[i-2..i-1] only for first element then... 
           Let's just do it word by word with extracts for correctness first, vectorize s0/s1. */
        (void)s0;
        break;
    }
    /* fallback: scalar schedule using already loaded first 16 */
    for(int i=16;i<64;i++){
        uint32_t x = w[i-15];
        uint32_t s0 = ROTR(x,7) ^ ROTR(x,18) ^ (x>>3);
        uint32_t y = w[i-2];
        uint32_t s1 = ROTR(y,17) ^ ROTR(y,19) ^ (y>>10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
    }
    for(int i=0;i<64;i++){
