#define ROTR(x,n) (((x)>>(n))|((x)<<(32-(n))))
#define ROUND(a,b,c,d,e,f,g,h,kk,ww) do { \
    uint32_t S1v = ROTR(e,6) ^ ROTR(e,11) ^ ROTR(e,25); \
    uint32_t ch = (e & f) ^ ((~e) & g); \
    uint32_t t1 = h + S1v + ch + (kk) + (ww); \
    uint32_t S0v = ROTR(a,2) ^ ROTR(a,13) ^ ROTR(a,22); \
    uint32_t maj = (a & b) ^ (a & c) ^ (b & c); \
    h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+S0v+maj; \
} while(0)

static void sha256_block(uint32_t st[8], const uint8_t block[64]){
    __m128i w0 = bswap128(_mm_loadu_si128((const __m128i*)(block+0)));
    __m128i w1 = bswap128(_mm_loadu_si128((const __m128i*)(block+16)));
    __m128i w2 = bswap128(_mm_loadu_si128((const __m128i*)(block+32)));
    __m128i w3 = bswap128(_mm_loadu_si128((const __m128i*)(block+48)));
