    for(int i=0;i<64;i++) ROUND(a,b,c,d,e,f,g,h, K[i], W[i]);
    st[0]+=a; st[1]+=b; st[2]+=c; st[3]+=d; st[4]+=e; st[5]+=f; st[6]+=g; st[7]+=h;
}

static inline uint32_t bswap32s(uint32_t x){ return (x<<24)|((x<<8)&0xff0000)|((x>>8)&0xff00)|(x>>24); }

