/* Process two consecutive 64-byte blocks of one message.
   Upper lane = block N (using state S), lower lane = block N+1 (using state after block N).
   We cannot know state after block N before computing it, so lanes are NOT independent
   for a single chained hash. This function instead demonstrates 2-block SIMD schedule
   only. Real chained hashing needs the rounds done scalar per block.
   Here we just time the SIMD message schedule for 2 blocks at once vs scalar, to see
   if schedule cost dominates. */
static inline __m256i sigma0(__m256i x){
    __m256i r7  = _mm256_or_si256(_mm256_srli_epi32(x,7),  _mm256_slli_epi32(x,25));
    __m256i r18 = _mm256_or_si256(_mm256_srli_epi32(x,18), _mm256_slli_epi32(x,14));
    return _mm256_xor_si256(_mm256_xor_si256(r7,r18), _mm256_srli_epi32(x,3));
}
static inline __m256i sigma1(__m256i x){
    __m256i r17 = _mm256_or_si256(_mm256_srli_epi32(x,17), _mm256_slli_epi32(x,15));
    __m256i r19 = _mm256_or_si256(_mm256_srli_epi32(x,19), _mm256_slli_epi32(x,13));
    return _mm256_xor_si256(_mm256_xor_si256(r17,r19), _mm256_srli_epi32(x,10));
}
static inline __m256i expand2(__m256i w0,__m256i w1,__m256i w2,__m256i w3){
    __m256i s0 = sigma0(_mm256_alignr_epi8(w1,w0,4));
    __m256i wim7 = _mm256_alignr_epi8(w3,w2,4);
    __m256i sum = _mm256_add_epi32(_mm256_add_epi32(w0,s0), wim7);
    __m256i s1 = sigma1(_mm256_srli_si256(w3,8));
    __m256i wn = _mm256_add_epi32(sum, s1);
    /* fix lanes 2 and 3 within each 128-bit half */
    uint32_t t[8]; _mm256_storeu_si256((__m256i*)t, wn);
    for(int lane=0; lane<2; lane++){
        int b=lane*4;
        uint32_t s1_0 = ((t[b]>>17)|(t[b]<<15))^((t[b]>>19)|(t[b]<<13))^(t[b]>>10);
        uint32_t s1_1 = ((t[b+1]>>17)|(t[b+1]<<15))^((t[b+1]>>19)|(t[b+1]<<13))^(t[b+1]>>10);
        t[b+2]+=s1_0; t[b+3]+=s1_1;
    }
    return _mm256_loadu_si256((const __m256i*)t);
}
/* compute message schedule for nblocks (multiple of 1) and write W words; returns count */
size_t schedule_all(const uint8_t *data, size_t nblocks, uint32_t *out){
    const __m256i mask = _mm256_setr_epi8(3,2,1,0,7,6,5,4,11,10,9,8,15,14,13,12,
                                          3,2,1,0,7,6,5,4,11,10,9,8,15,14,13,12);
    size_t nb = nblocks & ~1ULL;
    for(size_t b=0;b<nb;b+=2){
        __m256i w0=_mm256_shuffle_epi8(_mm256_set_m128i(_mm_loadu_si128((const __m128i*)(data+64*(b+1))), _mm_loadu_si128((const __m128i*)(data+64*b))), mask);
