        __m256i w3=_mm256_shuffle_epi8(_mm256_set_m128i(_mm_loadu_si128((const __m128i*)(data+64*(b+1)+48)), _mm_loadu_si128((const __m128i*)(data+64*b+48))), mask);
        uint32_t *o = out + b*64;
        _mm256_storeu_si256((__m256i*)(o+0), w0);   /* wrong layout: interleaved lanes. just store for timing */
        for(int i=16;i<64;i+=4){
